'use strict';
// 가이아 3인 파티 전용 필살기. 그림은 사용자 업로드 assets/gaia_cutins/A01..A04, S01..S04.
// 컷인 약 2초 동안 전투 정지 → 마지막 컷이 확대·투명화 → 동료 광역 공격.
// 전투 수치·마나·재사용 시간은 gaia_skills.js / town.js가 담당한다.
const GAIA_ULT = (()=>{
  let state=null, layer=null, stage=null, strips=[], caption=null, canvas=null, ink=null;
  const CUTIN_SEC=4.8, EFFECT_SEC=2.0;
  const FX_ART={"ground": "data:image/webp;base64,", "rain": "data:image/webp;base64,", "drop": "data:image/webp;base64,"};
  const dropArt=new Image();dropArt.src=FX_ART.drop;
  if(A.skicon){A.skicon.ky_ecstasy=FX_ART.ground;A.skicon.ky_waterfall=FX_ART.rain;}
  const colors={agatha:['#a87dff','#38164c'],sylvia:['#6ceaff','#0d405f']};
  function setup(){
    if(layer)return;
    const style=document.createElement('style');
    style.textContent=`
      #gaiaUlt{position:fixed;inset:0;z-index:29;display:none;overflow:hidden;pointer-events:none;isolation:isolate}
      #gaiaUlt .gu-stage{position:absolute;inset:0;overflow:hidden;background:radial-gradient(ellipse at 50% 55%,#323245bb,#090817df)}
      #gaiaUlt .gu-panel{position:absolute;width:55%;height:57%;padding:5px;box-sizing:border-box;background:#fff5e5;opacity:0;background:radial-gradient(ellipse at 55% 40%,#8665b2,#271a42 72%);box-shadow:inset 0 0 30px #fff5;will-change:transform,opacity;clip-path:polygon(0 0,100% 0,94% 100%,0 100%)}
      #gaiaUlt .gu-panel:nth-child(1){left:-2%;top:-3%;clip-path:polygon(0 0,100% 0,89% 100%,0 100%);z-index:1}
      #gaiaUlt .gu-panel:nth-child(2){right:-2%;top:-3%;clip-path:polygon(13% 0,100% 0,100% 100%,0 100%);z-index:2}
      #gaiaUlt .gu-panel:nth-child(3){left:-2%;bottom:-3%;clip-path:polygon(0 0,91% 0,100% 100%,0 100%);z-index:3}
      #gaiaUlt .gu-panel:nth-child(4){right:-2%;bottom:-3%;clip-path:polygon(0 0,100% 0,100% 100%,12% 100%);z-index:4}
      #gaiaUlt .gu-panel img{width:100%;height:100%;object-fit:cover;object-position:center 43%;filter:contrast(1.07) saturate(1.08)}
      #gaiaUlt .gu-panel::after{content:'';position:absolute;inset:0;box-shadow:inset 0 0 0 4px #ffffffa8,inset 0 0 90px #0007}
      #gaiaUlt .gu-caption{position:absolute;left:0;right:0;bottom:5%;text-align:center;z-index:8;color:#25142b;font:900 clamp(18px,3.5vw,42px)/1.35 sans-serif;letter-spacing:.02em;background:#fff9ed;border:3px solid #302034;border-radius:35px;padding:.3em .7em;margin:auto;max-width:85%;width:max-content;box-shadow:4px 5px 0 #17102188;opacity:0;transform:translateY(24px) scale(.8)}
      #gaiaUlt .gu-fx{position:absolute;inset:0;width:100%;height:100%}`;
    document.head.appendChild(style);
    layer=document.createElement('div');layer.id='gaiaUlt';layer.setAttribute('aria-hidden','true');
    stage=document.createElement('div');stage.className='gu-stage';layer.appendChild(stage);
    for(let i=0;i<4;i++){
      const panel=document.createElement('div');panel.className='gu-panel';
      const img=document.createElement('img');img.alt='';panel.append(img);stage.append(panel);strips.push(panel);
    }
    caption=document.createElement('div');caption.className='gu-caption';layer.append(caption);
    canvas=document.createElement('canvas');canvas.className='gu-fx';layer.append(canvas);ink=canvas.getContext('2d');
    document.body.appendChild(layer);
  }
  function casting(){return !!state&&state.phase==='cutin';}
  function start(who,mul){
    if(state||!combatMap()||!window.GAIA_PARTY)return false;
    const c=GAIA_PARTY.members()[who==='agatha'?0:1];
    if(!c||c.ko||c.hp<=0)return false;
    const enemies=monsters.some(m=>m&&!m.dead&&!m.removed&&!(m.vanishT>0)&&Math.hypot(m.x-c.x,m.y-c.y)<540);
    if(!enemies)return false;
    setup();
    const prefix=who==='agatha'?'A':'S',images=A.gaiaCutins||{};
    for(let i=0;i<4;i++){
      const src=images[prefix+String(i+1).padStart(2,'0')];
      const im=strips[i].firstChild;
      if(src){im.src=src;im.style.display='block';}else{im.removeAttribute('src');im.style.display='none';}
      strips[i].style.background=who==='agatha'
        ?`radial-gradient(ellipse at ${30+i*15}% 38%,#8c659b,#26122f 75%)`
        :`radial-gradient(ellipse at ${30+i*15}% 38%,#3f9abf,#0b253e 75%)`;
    }
    caption.textContent=who==='agatha'?'흐앙~~ 땅이 울린다구요!!':'앗!! 홍수가… 나버렸어요… ㅜ.ㅜ~~!!';
    stage.style.background=who==='agatha'?'#1b0a28':'#051a30';
    stage.style.opacity='1';
    layer.style.display='block';
    state={who,c,mul,phase:'cutin',t:0,fxT:0,wave:0,map:MAP,mapSerial:typeof fieldSerial!=='undefined'?fieldSerial:null};
    P.hold=false;
    drawCutin(0);
    return true;
  }
  function drawCutin(t){
    const delays=[.1,1,1.95,2.98],exit=Math.max(0,Math.min(1,(t-4.55)/.25));
    for(let i=0;i<4;i++){
      const age=t-delays[i],el=strips[i];
      if(age<0){el.style.opacity='0';continue;}
      const v=Math.min(1,age/.6),ease=1-Math.pow(1-v,3),sx=i%2?1:-1,sy=i<2?-1:1;
      el.style.opacity=String(Math.min(1,v*2)*(1-exit));
      el.style.transform=`translate3d(${sx*(1-ease)*48}%,${sy*(1-ease)*45}%,0) rotate(${sx*(1-ease)*8}deg) scale(${1+(1-ease)*.18})`;
      el.firstChild.style.transform=`scale(${1.09-Math.min(age,4)*.012})`;
    }
    const word=Math.max(0,Math.min(1,(t-3.85)/.25));
    caption.style.opacity=String(word*(1-exit));caption.style.transform=`translateY(${(1-word)*20}px) scale(${.85+word*.15})`;
    const flash=delays.reduce((m,d)=>Math.max(m,Math.max(0,1-Math.abs(t-d-.12)/.09)),0);
    stage.style.filter=`brightness(${1+flash*.7})`;
  }
  function pulse(){
    if(!state||state.preview)return;
    const {who,c,mul}=state,agatha=who==='agatha',radius=agatha?340:470;
    const mult=(agatha?5.2:1.3)*mul;
    const amount=Math.max(1,Math.round(Math.max(c.damage||0,NUM)*mult));
    for(const m of monsters){
      if(!m||m.dead||m.removed||(m.vanishT>0))continue;
      const dx=m.x-c.x,dy=m.y-c.y,dist=Math.hypot(dx,dy*1.22);
      if(dist>radius)continue;
      hitTarget(m,[dx/(dist||1),dy/(dist||1)],agatha,amount,agatha?55:4);
      if(agatha&&!m.dead)m.stun=Math.max(m.stun||0,(m.boss||m.elite)?.28:.7);
    }
    if(typeof SFX!=='undefined')SFX.play(agatha?'rock':'ice',agatha?.7:.48);
    if(agatha&&typeof skillShowImpact==='function')skillShowImpact('stone',c.x,c.y,260,3);
    if(!agatha)sfx.push({type:'iceburst',t:0,x:c.x,y:c.y-30,r:115});
    if(typeof HAP==='function')HAP(agatha?[55,25,80]:[25,10,22],2);
  }
  function paintEffect(t){
    if(!state||!canvas||!ink)return;
    const width=Math.max(1,innerWidth),height=Math.max(1,innerHeight),dpr=Math.min(devicePixelRatio||1,2);
    if(canvas.width!==Math.round(width*dpr)||canvas.height!==Math.round(height*dpr)){canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);}
    ink.setTransform(dpr,0,0,dpr,0,0);ink.clearRect(0,0,width,height);
    const duration=state.who==='agatha'?1.25:EFFECT_SEC,u=Math.min(1,t/duration),fade=Math.min(1,(duration-t)*4),c=state.c;
    const cx=width/2+(c.x-P.x)*Z,cy=height/2+(c.y-P.y)*Z;
    if(state.who==='sylvia'){
      // Four groups of five heavy drops. No flood, no thin rain overlay.
      for(let i=0;i<20;i++){
        const group=Math.floor(i/5),j=i%5,delay=group*.28+j*.025,age=t-delay,flight=.34;
        const x=(.1+((j*.193+group*.113)%.82))*width,y=height*(.43+((j*3+group)%5)*.105),size=Math.max(65,Math.min(145,width*.075))*(.82+(j%3)*.12);
        if(age>=0&&age<flight){
          const q=age/flight,px=x-(1-q)*width*.22,py=y-(1-q)*(height+size);
          ink.save();ink.globalAlpha=Math.min(1,age*15)*fade;
          if(dropArt.complete&&dropArt.naturalWidth)ink.drawImage(dropArt,px-size*.48,py-size*.8,size,size*1.15);
          ink.restore();
        }
        const hit=age-flight;
        if(hit>=0&&hit<.55){
          const f=(1-hit/.55)*fade,R=size*(.3+hit*2.6);
          ink.save();ink.globalAlpha=f;
          ink.fillStyle='#c5ffff';ink.beginPath();ink.ellipse(x,y,Math.max(0,size*(.45-hit)),Math.max(0,12-hit*15),0,0,7);ink.fill();
          ink.strokeStyle='#7aebff';ink.lineWidth=4;ink.beginPath();ink.ellipse(x,y,R,R*.23,0,0,7);ink.stroke();
          for(let k=0;k<11;k++){const a=k*2.39996,dist=hit*size*2.2,sx=x+Math.cos(a)*dist,sy=y-Math.sin(Math.min(1,hit/.55)*Math.PI)*size*.52+Math.sin(a)*dist*.2;
            ink.fillStyle=k%2?'#5ddaff':'#e8ffff';ink.beginPath();ink.ellipse(sx,sy,3+(k%3)*2,6+(k%3)*2,a,0,7);ink.fill();}
          ink.restore();
        }
      }
    }else{
     const wave=Math.min(1,u*1.32),rr=Math.hypot(width,height)*.75*wave;
      ink.fillStyle=`rgba(57,20,83,${.16*fade})`;ink.fillRect(0,0,width,height);
      for(let i=0;i<3;i++){
        const r=rr-i*94;if(r<0)continue;
        ink.strokeStyle=`rgba(${i===0?'255,230,255':'180,113,255'},${(.75-i*.17)*fade})`;
        ink.lineWidth=10-i*2;ink.beginPath();ink.ellipse(cx,cy,r,Math.max(2,r*.5),0,0,Math.PI*2);ink.stroke();
      }
      for(let i=0;i<23;i++){
        const a=i*2.4,r=rr*(.34+(i%7)*.09),px=cx+Math.cos(a)*r,py=cy+Math.sin(a)*r*.55;
        ink.fillStyle=`rgba(225,173,255,${fade*.8})`;ink.beginPath();ink.arc(px,py,2+i%4,0,Math.PI*2);ink.fill();
      }

    }
  }
  function finish(){
    state=null;if(layer){layer.style.display='none';ink&&ink.clearRect(0,0,canvas.width,canvas.height);}
  }
  function tick(dt,paused){
    if(!state)return false;
    if(paused&&!state.preview)return state.phase==='cutin';
    if(state.map!==MAP||(MAP==='field'&&state.mapSerial!==fieldSerial)){finish();return false;}
    if(state.phase==='cutin'){
      state.t+=dt*2;drawCutin(Math.min(CUTIN_SEC,state.t));
      if(state.t>=CUTIN_SEC){
        state.phase='effect';state.fxT=0;state.wave=0;stage.style.opacity='0';caption.style.opacity='0';
        stage.style.filter='none';
        if(state.who==='agatha'){pulse();state.wave=1;}else state.wave=0;
      }
      return true;
    }
    state.fxT+=dt;
    if(state.who==='sylvia'){
      const beats=[.34,.62,.90,1.18];
      while(state.wave<beats.length&&state.fxT>=beats[state.wave]){pulse();state.wave++;}
    }
    paintEffect(state.fxT);
    if(state.fxT>=(state.who==='agatha'?1.25:EFFECT_SEC)){stage.style.opacity='1';finish();}
    return false;
  }
  function preview(who){
    if(state)return false;setup();
    const member=window.GAIA_PARTY&&GAIA_PARTY.members()[who==='agatha'?0:1];
    const prefix=who==='agatha'?'A':'S',images=A.gaiaCutins||{};
    for(let i=0;i<4;i++){
      const src=images[prefix+String(i+1).padStart(2,'0')];
      const im=strips[i].firstChild;
      if(src){im.src=src;im.style.display='block';}else{im.removeAttribute('src');im.style.display='none';}
      strips[i].style.background=who==='agatha'
        ?`radial-gradient(ellipse at ${30+i*15}% 38%,#8c659b,#26122f 75%)`
        :`radial-gradient(ellipse at ${30+i*15}% 38%,#3f9abf,#0b253e 75%)`;
    }
    caption.textContent=who==='agatha'?'흐앙~~ 땅이 울린다구요!!':'앗!! 홍수가… 나버렸어요… ㅜ.ㅜ~~!!';
    stage.style.background=who==='agatha'?'#1b0a28':'#051a30';
    stage.style.opacity='1';
    layer.style.display='block';

    state={who,c:member||{x:P.x,y:P.y},mul:1,preview:true,phase:'cutin',t:0,fxT:0,wave:0,map:MAP,mapSerial:typeof fieldSerial!=='undefined'?fieldSerial:null};
    drawCutin(0);return true;
  }
  return {start,tick,casting,preview};
})();
window.GAIA_ULT=GAIA_ULT;
